"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[9413],{88999:e=>{e.exports=JSON.parse('{"functions":[{"name":"init","desc":"Bootstrap hook. Starts the friend-count poll.","params":[],"returns":[],"function_type":"static","source":{"line":48,"path":"src/Client/Features/Core/Controllers/SocialController.luau"}},{"name":"_startFriendCheckLoop","desc":"Opens the throttled Heartbeat poll, wires `friendsInServer.Changed` to\\n`ClientState.friendBoost`, and seeds both immediately in a spawned thread.\\n\\nNeither connection is ever disconnected \u2014 the controller runs for the\\nwhole session.","params":[],"returns":[],"function_type":"static","private":true,"source":{"line":63,"path":"src/Client/Features/Core/Controllers/SocialController.luau"}}],"properties":[],"types":[],"name":"SocialController","desc":"Keeps the friends-in-server boost current.\\n\\nRoblox has no signal for \\"a friend joined this server\\", so this polls:\\na Heartbeat connection with a `CHECK_INTERVAL`-second (20s) throttle\\nrecounts `getFriendsInServer(LocalPlayer)` and writes it to\\n`SocialController.friendsInServer`. Whenever that count changes,\\n`ClientState.friendBoost` is set to `BoostData.getBoostPerFriend(count)`.\\n\\nAn immediate seed runs in a `task.spawn` at init so the boost is right\\nfrom the first frame rather than up to 20 seconds late \u2014 the friends\\nlookup yields, hence the spawn.\\n\\nThe `Menus` HUD component reads `ClientState.friendBoost` for its\\n`{value * 100}%` label. That button is gated on the `FriendBonus` feature\\nflag; this controller is not, so the boost state stays accurate whether or\\nnot it is displayed.\\n\\nCopyright (c) 2026 firebit. All rights reserved.\\nfirebit/murder-escape - proprietary and confidential.","realm":["Client"],"source":{"line":25,"path":"src/Client/Features/Core/Controllers/SocialController.luau"}}')}}]);